import { sql } from 'drizzle-orm';
import {
  boolean,
  check,
  customType,
  foreignKey,
  index,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  text,
  timestamp,
  unique,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';

// Conventions (as in identity): UUIDv7 ids generated by the application, timestamptz, statuses as
// text + CHECK. Every tenant-owned table has organization_id and a unique (organization_id, id)
// key so other tables can reference it with a composite foreign key: a reference into another
// tenant is then not just filtered out, it cannot be written at all. Row Level Security policies
// live in hand-written migrations (drizzle/0003_*.sql).

const timestamptz = (name: string) => timestamp(name, { withTimezone: true, mode: 'date' });
const createdAt = () => timestamptz('created_at').notNull().defaultNow();
const updatedAt = () => timestamptz('updated_at').notNull().defaultNow();

const bytea = customType<{ data: Buffer }>({
  dataType: () => 'bytea',
});

// ---- applications -------------------------------------------------------------------------------

export const applications = pgTable(
  'applications',
  {
    id: uuid('id').primaryKey(),
    organizationId: uuid('organization_id').notNull(),
    name: text('name').notNull(),
    description: text('description'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    archivedAt: timestamptz('archived_at'),
  },
  (table) => [
    unique('applications_org_id_key').on(table.organizationId, table.id),
    // A live application name is unique per organization, ignoring case; archiving frees it.
    uniqueIndex('applications_org_name_live_idx')
      .on(table.organizationId, sql`lower(${table.name})`)
      .where(sql`${table.archivedAt} is null`),
  ],
);

// ---- event types --------------------------------------------------------------------------------

export const eventTypes = pgTable(
  'event_types',
  {
    id: uuid('id').primaryKey(),
    organizationId: uuid('organization_id').notNull(),
    name: text('name').notNull(),
    description: text('description'),
    /** JSON Schema (draft 2020-12) for payloads of this type, or null for no validation. */
    schema: jsonb('schema'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    archivedAt: timestamptz('archived_at'),
  },
  (table) => [
    unique('event_types_org_id_key').on(table.organizationId, table.id),
    // Names are never reused, not even after archiving (ADR-0025).
    unique('event_types_org_name_key').on(table.organizationId, table.name),
    check('event_types_name_format', sql`${table.name} ~ '^[a-z0-9][a-z0-9_.-]{0,127}$'`),
  ],
);

// ---- endpoints ----------------------------------------------------------------------------------

export const endpoints = pgTable(
  'endpoints',
  {
    id: uuid('id').primaryKey(),
    organizationId: uuid('organization_id').notNull(),
    applicationId: uuid('application_id').notNull(),
    url: text('url').notNull(),
    description: text('description'),
    enabled: boolean('enabled').notNull().default(true),
    disabledReason: text('disabled_reason'),
    disabledAt: timestamptz('disabled_at'),
    /** Health tracked by the dispatcher (ADR-0033): the failure streak and the circuit breaker. */
    consecutiveFailures: integer('consecutive_failures').notNull().default(0),
    firstFailureAt: timestamptz('first_failure_at'),
    circuitOpenUntil: timestamptz('circuit_open_until'),
    circuitTrips: integer('circuit_trips').notNull().default(0),
    rateLimitPerSecond: integer('rate_limit_per_second'),
    /** Custom request headers: lowercase name to value. Validated before it is stored. */
    headers: jsonb('headers').notNull().default({}),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    archivedAt: timestamptz('archived_at'),
  },
  (table) => [
    unique('endpoints_org_id_key').on(table.organizationId, table.id),
    foreignKey({
      name: 'endpoints_application_fk',
      columns: [table.organizationId, table.applicationId],
      foreignColumns: [applications.organizationId, applications.id],
    }),
    index('endpoints_application_idx').on(table.organizationId, table.applicationId),
    check(
      'endpoints_rate_limit_range',
      sql`${table.rateLimitPerSecond} is null or ${table.rateLimitPerSecond} between 1 and 1000`,
    ),
    check('endpoints_url_length', sql`char_length(${table.url}) <= 2048`),
  ],
);

/** Which event types an endpoint receives. No rows means every event type. */
export const endpointEventTypes = pgTable(
  'endpoint_event_types',
  {
    organizationId: uuid('organization_id').notNull(),
    endpointId: uuid('endpoint_id').notNull(),
    eventTypeId: uuid('event_type_id').notNull(),
  },
  (table) => [
    primaryKey({ columns: [table.endpointId, table.eventTypeId] }),
    foreignKey({
      name: 'endpoint_event_types_endpoint_fk',
      columns: [table.organizationId, table.endpointId],
      foreignColumns: [endpoints.organizationId, endpoints.id],
    }),
    foreignKey({
      name: 'endpoint_event_types_event_type_fk',
      columns: [table.organizationId, table.eventTypeId],
      foreignColumns: [eventTypes.organizationId, eventTypes.id],
    }),
    index('endpoint_event_types_event_type_idx').on(table.organizationId, table.eventTypeId),
  ],
);

// ---- signing secrets ----------------------------------------------------------------------------

export const SECRET_STATUSES = ['active', 'previous'] as const;

/**
 * Signing secrets, envelope-encrypted (ADR-0026). An endpoint has one active secret; rotation
 * (Phase 7) keeps the old one as `previous` until `expires_at`, so both sign during the window.
 */
export const endpointSecrets = pgTable(
  'endpoint_secrets',
  {
    id: uuid('id').primaryKey(),
    organizationId: uuid('organization_id').notNull(),
    endpointId: uuid('endpoint_id').notNull(),
    status: text('status').notNull().default('active'),
    ciphertext: bytea('ciphertext').notNull(),
    wrappedDataKey: bytea('wrapped_data_key').notNull(),
    keyId: text('key_id').notNull(),
    createdAt: createdAt(),
    expiresAt: timestamptz('expires_at'),
  },
  (table) => [
    unique('endpoint_secrets_org_id_key').on(table.organizationId, table.id),
    foreignKey({
      name: 'endpoint_secrets_endpoint_fk',
      columns: [table.organizationId, table.endpointId],
      foreignColumns: [endpoints.organizationId, endpoints.id],
    }),
    uniqueIndex('endpoint_secrets_one_active_idx')
      .on(table.endpointId)
      .where(sql`${table.status} = 'active'`),
    check('endpoint_secrets_status', sql`${table.status} in ('active', 'previous')`),
  ],
);

// ---- API keys -----------------------------------------------------------------------------------

/** Scopes are validated against the contract list before they are stored (ADR-0027). */
export const apiKeys = pgTable(
  'api_keys',
  {
    id: uuid('id').primaryKey(),
    organizationId: uuid('organization_id').notNull(),
    applicationId: uuid('application_id').notNull(),
    name: text('name').notNull(),
    prefix: text('prefix').notNull(),
    /** Hex SHA-256 of the key. The key itself is never stored. */
    keyHash: text('key_hash').notNull(),
    scopes: text('scopes').array().notNull(),
    createdBy: uuid('created_by'),
    createdAt: createdAt(),
    lastUsedAt: timestamptz('last_used_at'),
    expiresAt: timestamptz('expires_at'),
    revokedAt: timestamptz('revoked_at'),
  },
  (table) => [
    unique('api_keys_org_id_key').on(table.organizationId, table.id),
    // Authentication looks a key up by digest alone, so the digest is unique across tenants.
    unique('api_keys_key_hash_key').on(table.keyHash),
    foreignKey({
      name: 'api_keys_application_fk',
      columns: [table.organizationId, table.applicationId],
      foreignColumns: [applications.organizationId, applications.id],
    }),
    index('api_keys_application_idx').on(table.organizationId, table.applicationId),
    check('api_keys_scopes_not_empty', sql`cardinality(${table.scopes}) > 0`),
  ],
);

// ---- messages -----------------------------------------------------------------------------------

/** One event sent by a tenant (ADR-0030). Immutable once stored. */
export const messages = pgTable(
  'messages',
  {
    id: uuid('id').primaryKey(),
    organizationId: uuid('organization_id').notNull(),
    applicationId: uuid('application_id').notNull(),
    eventTypeId: uuid('event_type_id').notNull(),
    payload: jsonb('payload').notNull(),
    payloadBytes: integer('payload_bytes').notNull(),
    idempotencyKey: text('idempotency_key').notNull(),
    createdAt: createdAt(),
  },
  (table) => [
    unique('messages_org_id_key').on(table.organizationId, table.id),
    foreignKey({
      name: 'messages_application_fk',
      columns: [table.organizationId, table.applicationId],
      foreignColumns: [applications.organizationId, applications.id],
    }),
    foreignKey({
      name: 'messages_event_type_fk',
      columns: [table.organizationId, table.eventTypeId],
      foreignColumns: [eventTypes.organizationId, eventTypes.id],
    }),
    index('messages_application_created_idx').on(
      table.organizationId,
      table.applicationId,
      table.createdAt.desc(),
    ),
  ],
);

/**
 * Remembers an Idempotency-Key for a retention window. The primary key is (application, key); an
 * expired row is replaced by the next request that uses the key.
 */
export const idempotencyKeys = pgTable(
  'idempotency_keys',
  {
    organizationId: uuid('organization_id').notNull(),
    applicationId: uuid('application_id').notNull(),
    key: text('key').notNull(),
    /** SHA-256 of the event type and the canonical payload, to tell a retry from a different request. */
    requestHash: text('request_hash').notNull(),
    messageId: uuid('message_id').notNull(),
    createdAt: createdAt(),
    expiresAt: timestamptz('expires_at').notNull(),
  },
  (table) => [
    primaryKey({ columns: [table.applicationId, table.key] }),
    foreignKey({
      name: 'idempotency_keys_application_fk',
      columns: [table.organizationId, table.applicationId],
      foreignColumns: [applications.organizationId, applications.id],
    }),
    foreignKey({
      name: 'idempotency_keys_message_fk',
      columns: [table.organizationId, table.messageId],
      foreignColumns: [messages.organizationId, messages.id],
    }),
    index('idempotency_keys_expires_idx').on(table.expiresAt),
  ],
);

// ---- deliveries ---------------------------------------------------------------------------------

export const DELIVERY_STATUSES = ['pending', 'in_progress', 'succeeded', 'failed'] as const;

/**
 * The state of one message to one endpoint. Fan-out creates the rows `pending` and due now; the
 * dispatcher (Phase 6) claims and advances them.
 */
export const deliveries = pgTable(
  'deliveries',
  {
    id: uuid('id').primaryKey(),
    organizationId: uuid('organization_id').notNull(),
    applicationId: uuid('application_id').notNull(),
    messageId: uuid('message_id').notNull(),
    endpointId: uuid('endpoint_id').notNull(),
    status: text('status').notNull().default('pending'),
    attemptCount: integer('attempt_count').notNull().default(0),
    nextAttemptAt: timestamptz('next_attempt_at').notNull().defaultNow(),
    /** While `in_progress`: when the claim expires and another worker may take the delivery. */
    lockedUntil: timestamptz('locked_until'),
    lastAttemptAt: timestamptz('last_attempt_at'),
    lastStatusCode: integer('last_status_code'),
    lastErrorClass: text('last_error_class'),
    /** `attempt_count` when the current cycle began; replay starts a new cycle (ADR-0033). */
    cycleBase: integer('cycle_base').notNull().default(0),
    completedAt: timestamptz('completed_at'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    unique('deliveries_org_id_key').on(table.organizationId, table.id),
    unique('deliveries_message_endpoint_key').on(table.messageId, table.endpointId),
    foreignKey({
      name: 'deliveries_message_fk',
      columns: [table.organizationId, table.messageId],
      foreignColumns: [messages.organizationId, messages.id],
    }),
    foreignKey({
      name: 'deliveries_endpoint_fk',
      columns: [table.organizationId, table.endpointId],
      foreignColumns: [endpoints.organizationId, endpoints.id],
    }),
    index('deliveries_due_idx')
      .on(table.nextAttemptAt)
      .where(sql`${table.status} = 'pending'`),
    index('deliveries_tenant_due_idx')
      .on(table.organizationId, table.nextAttemptAt)
      .where(sql`${table.status} = 'pending'`),
    index('deliveries_in_progress_idx')
      .on(table.lockedUntil)
      .where(sql`${table.status} = 'in_progress'`),
    index('deliveries_endpoint_idx').on(
      table.organizationId,
      table.endpointId,
      table.createdAt.desc(),
    ),
    check(
      'deliveries_status',
      sql`${table.status} in ('pending', 'in_progress', 'succeeded', 'failed')`,
    ),
  ],
);

// ---- consumers ----------------------------------------------------------------------------------

/** Which events each consumer already applied, so a redelivered event is a no-op (ADR-0029). */
export const processedEvents = pgTable(
  'processed_events',
  {
    consumer: text('consumer').notNull(),
    eventId: uuid('event_id').notNull(),
    processedAt: timestamptz('processed_at').notNull().defaultNow(),
  },
  (table) => [primaryKey({ columns: [table.consumer, table.eventId] })],
);

// ---- integration --------------------------------------------------------------------------------

/**
 * Events recorded in the same transaction as the change they describe. The relay that publishes
 * them to RabbitMQ is built with message ingestion.
 */
export const outboxEvents = pgTable(
  'outbox_events',
  {
    id: uuid('id').primaryKey(),
    type: text('type').notNull(),
    version: integer('version').notNull(),
    occurredAt: timestamptz('occurred_at').notNull(),
    organizationId: uuid('organization_id'),
    actorId: uuid('actor_id'),
    correlationId: text('correlation_id').notNull(),
    causationId: uuid('causation_id'),
    payload: jsonb('payload').notNull(),
    publishedAt: timestamptz('published_at'),
  },
  (table) => [
    index('outbox_events_unpublished_idx')
      .on(table.occurredAt)
      .where(sql`${table.publishedAt} is null`),
  ],
);

export const schema = {
  applications,
  eventTypes,
  endpoints,
  endpointEventTypes,
  endpointSecrets,
  apiKeys,
  messages,
  idempotencyKeys,
  deliveries,
  processedEvents,
  outboxEvents,
};
export type IngestSchema = typeof schema;
